      "features/todo-management.feature:Main and footer are hidden when there are no todos"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/todo-management.feature:Create a new todo by pressing Enter",
      "features/todo-management.feature:Creating a todo with only whitespace does nothing"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/todo-management.feature:Mark a todo as complete",
      "features/todo-management.feature:Unmark a completed todo",
      "features/todo-management.feature:Toggle all marks every todo complete",
      "features/todo-management.feature:Toggle all marks every todo active when all are complete",
      "features/todo-management.feature:Toggle-all checkbox updates when individual items change",
      "features/todo-management.feature:Clear completed removes all completed todos",
      "features/todo-management.feature:Clear completed button is hidden when there are no completed todos",
      "features/todo-management.feature:Clear completed button is visible when there are completed todos"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/todo-management.feature:Click the destroy button removes a todo"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/todo-management.feature:Double-click a todo label enters edit mode",
      "features/todo-management.feature:Save an edited todo on Enter",
      "features/todo-management.feature:Save an edited todo on blur",
      "features/todo-management.feature:Delete a todo when edit input is empty",
      "features/todo-management.feature:Cancel editing with Escape restores the original title"
    ]
  },
  "watch6": {
    "scenarios": [
      "features/todo-management.feature:Counter shows number of active todos",
      "features/todo-management.feature:Counter uses plural form for zero items",
      "features/todo-management.feature:Counter uses plural form for multiple items"
    ]
  },
  "watch7": {
    "scenarios": [
      "features/todo-management.feature:Todos persist across page reload",
      "features/todo-management.feature:Completed state persists across page reload",
      "features/todo-management.feature:Editing state is not persisted across reload"
    ]
  },
  "watch8": {
    "scenarios": [
      "features/todo-filtering.feature:Default route shows all todos",
      "features/todo-filtering.feature:Active route shows only incomplete todos",
      "features/todo-filtering.feature:Completed route shows only completed todos",
      "features/todo-filtering.feature:Marking a todo complete hides it in the active filter",
      "features/todo-filtering.feature:Unmarking a todo shows it in the active filter",
      "features/todo-filtering.feature:Selected class is applied to the current filter link",
      "features/todo-filtering.feature:Selected class moves when navigating to a different filter",
      "features/todo-filtering.feature:Active filter persists across page reload",
      "features/todo-filtering.feature:Clearing a todo updates the list in filtered view"
    ]
  }
}

