const { Browser } = require('happy-dom');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');

function TodoWorld() {
  this.browser = null;
  this.page = null;
}

function escapeForDocumentWrite(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r');
}

TodoWorld.prototype.loadApp = function () {
  const indexPath = path.resolve(__dirname, '../../index.html');
  const html = fs.readFileSync(indexPath, 'utf8');
  const escaped = escapeForDocumentWrite(html);
  this.page.evaluate(
    `document.write('${escaped}'); document.close();`
  );
  this.page.waitUntilComplete();
};

TodoWorld.prototype.evaluate = function (script) {
  return this.page.evaluate(script);
};

TodoWorld.prototype.getText = function (selector) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.textContent : null; })()`
  );
};

TodoWorld.prototype.getAttribute = function (selector, attr) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.getAttribute('${attr}') : null; })()`
  );
};

TodoWorld.prototype.isVisible = function (selector) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (!el) return false; const style = window.getComputedStyle(el); return style.display !== 'none' && style.visibility !== 'hidden' && el.offsetParent !== null; })()`
  );
};

TodoWorld.prototype.hasClass = function (selector, cls) {
  return this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); return el ? el.classList.contains('${cls}') : false; })()`
  );
};

TodoWorld.prototype.clickElement = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) el.click(); })()`
  );
};

TodoWorld.prototype.setInputValue = function (selector, value) {
  const escaped = escapeForDocumentWrite(value);
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.value = '${escaped}'; el.dispatchEvent(new Event('input', { bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressEnter = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressEscape = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Escape', keyCode: 27, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.pressTab = function (selector) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('${selector}'); if (el) { el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', keyCode: 9, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Tab', keyCode: 9, bubbles: true })); } })()`
  );
};

TodoWorld.prototype.exists = function (selector) {
  return this.page.evaluate(
    `document.querySelector('${selector}') !== null`
  );
};

TodoWorld.prototype.querySelectorAllCount = function (selector) {
  return this.page.evaluate(
    `document.querySelectorAll('${selector}').length`
  );
};

TodoWorld.prototype.clearLocalStorage = function () {
  this.page.evaluate('localStorage.clear()');
};

TodoWorld.prototype.setLocalStorage = function (key, value) {
  const escaped = escapeForDocumentWrite(value);
  this.page.evaluate(`localStorage.setItem('${key}', '${escaped}')`);
};

TodoWorld.prototype.getLocalStorage = function (key) {
  return this.page.evaluate(`localStorage.getItem('${key}')`);
};

setWorldConstructor(TodoWorld);

Before(function () {
  this.browser = new Browser();
  this.page = this.browser.newPage();
});

After(function () {
  if (this.browser) {
    this.browser.close();
    this.browser = null;
    this.page = null;
  }
});

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// ─── Helper: evaluate a script with the world's page ───
function w(step, script) {
  return step.world.evaluate(script);
}

function escape(str) {
  return str.replace(/'/g, "\\'").replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/\r/g, '\\r');
}

// Find a todo <li> by its label text
function todoSelector(title) {
  return `li:has(div.view label:contains("${escape(title)}"))`;
}

function todoExists(title) {
  return `document.querySelector('${todoSelector(title)}') !== null`;
}

function todoCompleted(title) {
  return `document.querySelector('${todoSelector(title)}') !== null && document.querySelector('${todoSelector(title)}').classList.contains('completed')`;
}

function toggleCheckboxSelector(title) {
  return `${todoSelector(title)} div.view input.toggle`;
}

function destroySelector(title) {
  return `${todoSelector(title)} div.view button.destroy`;
}

function editInputSelector(title) {
  return `${todoSelector(title)} input.edit`;
}

function labelSelector(title) {
  return `${todoSelector(title)} div.view label`;
}

// ─── Given steps ───

Given('the todo app is loaded with a fresh localStorage', function () {
  this.loadApp();
  this.clearLocalStorage();
});

Given('the app has no todos', function () {
  this.loadApp();
  this.clearLocalStorage();
  // Verify no todo items exist
  const count = this.querySelectorAllCount('.todo-list li');
  // Remove sample items from template
  this.evaluate(
    `document.querySelector('.todo-list').innerHTML = '';`
  );
});

Given('a todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

Given('a completed todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
  // Click the toggle checkbox
  const sel = `li:last-child div.view input.toggle`;
  this.clickElement(sel);
});

Given('an active todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

Given('todo items {word} and {word} and {word} exist', function (a, b, c) {
  [a, b, c].forEach(t => {
    this.setInputValue('.new-todo', t);
    this.pressEnter('.new-todo');
  });
});

Given('active todo items {word} and {word} exist', function (a, b) {
  [a, b].forEach(t => {
    this.setInputValue('.new-todo', t);
    this.pressEnter('.new-todo');
  });
});

Given('completed todo items {word} and {word} exist', function (a, b) {
  [a, b].forEach(t => {
    this.setInputValue('.new-todo', t);
    this.pressEnter('.new-todo');
  });
  // Mark both as completed
  const items = this.querySelectorAllCount('.todo-list li');
  for (let i = 0; i < items; i++) {
    this.clickElement(`.todo-list li:nth-child(${i + 1}) div.view input.toggle`);
  }
});

Given('all todo items are completed', function () {
  this.clickElement('.toggle-all');
});

Given('the app is at route {string}', function (route) {
  // Set the hash and dispatch a hashchange event
  this.page.evaluate(
    `window.location.hash = '${escape(route)}'; window.dispatchEvent(new HashChangeEvent('hashchange'));`
  );
});

Given('the todo {string} is being edited', function (title) {
  // First ensure the todo exists
  if (!this.evaluate(todoExists(title))) {
    this.setInputValue('.new-todo', title);
    this.pressEnter('.new-todo');
  }
  // Double-click the label to enter edit mode
  this.page.evaluate(
    `(() => { const li = document.querySelector('${todoSelector(title)}'); if (li) { const label = li.querySelector('div.view label'); if (label) { label.dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); } } })()`
  );
});

Given('the input field is focused', function () {
  this.page.evaluate('document.querySelector(".new-todo").focus()');
});

Given('only active todos are visible in the list', function () {
  // Already at #/active, filter applied
});

Given('{string} is visible under the completed filter', function (title) {
  // Navigate to completed filter
  this.page.evaluate(
    `window.location.hash = '#/completed'; window.dispatchEvent(new HashChangeEvent('hashchange'));`
  );
});

// ─── When steps ───

When('I type {string} into the new-todo input and press Enter', function (text) {
  this.setInputValue('.new-todo', text);
  this.pressEnter('.new-todo');
});

When('I click the toggle checkbox on {string}', function (title) {
  this.clickElement(toggleCheckboxSelector(title));
});

When('I click the {string} checkbox', function (id) {
  this.clickElement(`#${escape(id)}`);
});

When('I click the {string} button', function (text) {
  if (text === 'Clear completed') {
    this.clickElement('.clear-completed');
  }
});

When('I click the destroy button on {string}', function (title) {
  this.clickElement(destroySelector(title));
});

When('I double-click the label of {string}', function (title) {
  this.page.evaluate(
    `(() => { const li = document.querySelector('${todoSelector(title)}'); if (li) { const label = li.querySelector('div.view label'); if (label) { label.dispatchEvent(new MouseEvent('dblclick', { bubbles: true })); } } })()`
  );
});

When('I change the edit input to {string} and press Enter', function (text) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('input.edit:not([style*=\"display: none\"]):not([type=\"hidden\"])'); if (el) { el.value = '${escape(text)}'; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true })); } })()`
  );
});

When('I change the edit input to {string} and press Tab to blur', function (text) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('input.edit:not([style*=\"display: none\"]):not([type=\"hidden\"])'); if (el) { el.value = '${escape(text)}'; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', keyCode: 9, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Tab', keyCode: 9, bubbles: true })); } })()`
  );
});

When('I change the edit input to {string} and press Escape', function (text) {
  this.page.evaluate(
    `(() => { const el = document.querySelector('input.edit:not([style*=\"display: none\"]):not([type=\"hidden\"])'); if (el) { el.value = '${escape(text)}'; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Escape', keyCode: 27, bubbles: true })); } })()`
  );
});

When('I clear the edit input and press Enter', function () {
  this.page.evaluate(
    `(() => { const el = document.querySelector('input.edit:not([style*=\"display: none\"]):not([type=\"hidden\"])'); if (el) { el.value = ''; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true })); } })()`
  );
});

When('I mark {string} as completed', function (title) {
  this.clickElement(toggleCheckboxSelector(title));
});

When('I unmark {string}', function (title) {
  this.clickElement(toggleCheckboxSelector(title));
});

When('the page is reloaded', function () {
  // Simulate page reload by re-loading HTML and re-running app
  this.loadApp();
  // Trigger route handler
  this.page.evaluate(
    `if (window.onhashchange) window.onhashchange();`
  );
});

When('I navigate to route {string}', function (route) {
  this.page.evaluate(
    `window.location.hash = '${escape(route)}'; window.dispatchEvent(new HashChangeEvent('hashchange'));`
  );
});

When('I create a new todo {string}', function (title) {
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

// ─── Then steps ───

Then('the {string} section is not visible', function (sectionId) {
  const visible = this.isVisible(sectionId);
  assert.strictEqual(visible, false, `Expected ${sectionId} to be hidden`);
});

Then('the {string} section is visible', function (sectionId) {
  const visible = this.isVisible(sectionId);
  assert.strictEqual(visible, true, `Expected ${sectionId} to be visible`);
});

Then('a new todo item with title {string} appears in the list', function (title) {
  const exists = this.evaluate(todoExists(title));
  assert.strictEqual(exists, true, `Expected todo "${title}" to appear in list`);
});

Then('the new-todo input is cleared', function () {
  const val = this.page.evaluate('document.querySelector(".new-todo").value');
  assert.strictEqual(val, '', 'Expected new-todo input to be cleared');
});

Then('no new todo item is created', function () {
  const count = this.querySelectorAllCount('.todo-list li');
  assert.strictEqual(count, 0, 'Expected no todo items to be created');
});

Then('the {string} item has the {string} class', function (title, cls) {
  const hasIt = this.hasClass(todoSelector(title), cls);
  assert.strictEqual(hasIt, true, `Expected todo "${title}" to have class "${cls}"`);
});

Then('the {string} item does not have the {string} class', function (title, cls) {
  const hasIt = this.hasClass(todoSelector(title), cls);
  assert.strictEqual(hasIt, false, `Expected todo "${title}" to NOT have class "${cls}"`);
});

