      html += '<label>' + this._escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';

      if (this.editingId === todo.id) {
        html += '<input class="edit" value="' + this._escapeHtml(todo.title) + '">';
      } else {
        html += '<input class="edit" value="' + this._escapeHtml(todo.title) + '" style="display:none">';
      }
      html += '</li>';
    }, this);

