const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

function esc(str) {
  return str.replace(/'/g, "\\'").replace(/\\/g, '\\\\');
}

// JS expression to find a todo <li> by its label text
function findLi(title) {
  return "Array.from(document.querySelectorAll('.todo-list li')).filter(function(li){var lb=li.querySelector('div.view label');return lb&&lb.textContent==='" + esc(title) + "';})[0]";
}

function liExists(title) { return findLi(title) + '!==undefined'; }

function findToggle(title) { return "(function(){var li=" + findLi(title) + ";return li?li.querySelector('div.view input.toggle'):null;})()"; }

function findDestroy(title) { return "(function(){var li=" + findLi(title) + ";return li?li.querySelector('div.view button.destroy'):null;})()"; }

function findLabel(title) { return "(function(){var li=" + findLi(title) + ";return li?li.querySelector('div.view label'):null;})()"; }

function liClass(title, cls) { return "(function(){var li=" + findLi(title) + ";return li?li.classList.contains('" + esc(cls) + "'):false;})()"; }

function toggleChecked(title) { return "(function(){var t=" + findToggle(title) + ";return t?t.checked:false;})()"; }

// ─── Given ───

Given('the todo app is loaded with a fresh localStorage', function () {
  this.loadApp();
  this.clearLocalStorage();
});

Given('the app has no todos', function () {
  this.loadApp();
  this.clearLocalStorage();
  this.evaluate("document.querySelector('.todo-list').innerHTML='';");
});

Given('a todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

Given('a completed todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
  this.clickElement('li:last-child div.view input.toggle');
});

Given('an active todo item {string} exists', function (title) {
  this.clickElement('.new-todo');
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

Given('todo items {string} and {string} exist', function (a, b) {
  var self = this;
  [a, b].forEach(function (t) {
    self.setInputValue('.new-todo', t);
    self.pressEnter('.new-todo');
  });
});

Given('todo items {string} and {string} and {string} exist', function (a, b, c) {
  var self = this;
  [a, b, c].forEach(function (t) {
    self.setInputValue('.new-todo', t);
    self.pressEnter('.new-todo');
  });
});

Given('active todo items {string} and {string} exist', function (a, b) {
  var self = this;
  [a, b].forEach(function (t) {
    self.setInputValue('.new-todo', t);
    self.pressEnter('.new-todo');
  });
});

Given('completed todo items {string} and {string} exist', function (a, b) {
  var self = this;
  [a, b].forEach(function (t) {
    self.setInputValue('.new-todo', t);
    self.pressEnter('.new-todo');
  });
  var count = this.querySelectorAllCount('.todo-list li');
  for (var i = 0; i < count; i++) {
    this.clickElement('.todo-list li:nth-child(' + (i + 1) + ') div.view input.toggle');
  }
});

Given('all todo items are completed', function () {
  this.clickElement('.toggle-all');
});

Given('the app is at route {string}', function (route) {
  this.page.evaluate("window.location.hash='" + esc(route) + "';window.dispatchEvent(new HashChangeEvent('hashchange'));");
});

Given('the todo {string} is being edited', function (title) {
  var sel = findLi(title);
  var exists = this.evaluate(sel + '!==undefined');
  if (!exists) {
    this.setInputValue('.new-todo', title);
    this.pressEnter('.new-todo');
  }
  // Double-click the label
  this.page.evaluate("(function(){var li=" + findLi(title) + ";if(li){var lb=li.querySelector('div.view label');if(lb)lb.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));}})()");
});

Given('the input field is focused', function () {
  this.page.evaluate('document.querySelector(".new-todo").focus()');
});

Given('only active todos are visible in the list', function () {});

Given('{string} is visible under the completed filter', function () {
  this.page.evaluate("window.location.hash='#/completed';window.dispatchEvent(new HashChangeEvent('hashchange'));");
});

// ─── When ───

When('I type {string} into the new-todo input and press Enter', function (text) {
  this.setInputValue('.new-todo', text);
  this.pressEnter('.new-todo');
});

When('I click the toggle checkbox on {string}', function (title) {
  var toggleExpr = findToggle(title);
  this.page.evaluate("(function(){var t=" + toggleExpr + ";if(t)t.click();})()");
});

When('I click the {string} checkbox', function (id) {
  this.clickElement('#' + esc(id));
});

When('I click the {string} button', function (text) {
  if (text === 'Clear completed') {
    this.clickElement('.clear-completed');
  }
});

When('I click the destroy button on {string}', function (title) {
  var destroyExpr = findDestroy(title);
  this.page.evaluate("(function(){var d=" + destroyExpr + ";if(d)d.click();})()");
});

When('I double-click the label of {string}', function (title) {
  this.page.evaluate("(function(){var li=" + findLi(title) + ";if(li){var lb=li.querySelector('div.view label');if(lb)lb.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));}})()");
});

When('I change the edit input to {string} and press Enter', function (text) {
  this.page.evaluate(
    "(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='" + esc(text) + "';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',keyCode:13,bubbles:true}));}})()"
  );
});

When('I change the edit input to {string} and press Tab to blur', function (text) {
  this.page.evaluate(
    "(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='" + esc(text) + "';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',keyCode:9,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Tab',keyCode:9,bubbles:true}));}})()"
  );
});

When('I change the edit input to {string} and press Escape', function (text) {
  this.page.evaluate(
    "(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='" + esc(text) + "';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',keyCode:27,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Escape',keyCode:27,bubbles:true}));}})()"
  );
});

When('I clear the edit input and press Enter', function () {
  this.page.evaluate(
    "(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',keyCode:13,bubbles:true}));}})()"
  );
});

When('I mark {string} as completed', function (title) {
  var toggleExpr = findToggle(title);
  this.page.evaluate("(function(){var t=" + toggleExpr + ";if(t)t.click();})()");
});

When('I unmark {string}', function (title) {
  var toggleExpr = findToggle(title);
  this.page.evaluate("(function(){var t=" + toggleExpr + ";if(t)t.click();})()");
});

When('the page is reloaded', function () {
  this.loadApp();
  this.page.evaluate('if(window.onhashchange)window.onhashchange();');
});

When('I navigate to route {string}', function (route) {
  this.page.evaluate("window.location.hash='" + esc(route) + "';window.dispatchEvent(new HashChangeEvent('hashchange'));");
});

When('I create a new todo {string}', function (title) {
  this.setInputValue('.new-todo', title);
  this.pressEnter('.new-todo');
});

// ─── Then ───

function mapSel(id) {
  if (id === '#main') return '.main';
  if (id === '#footer') return '.footer';
  return id;
}

Then('the {string} section is not visible', function (sectionId) {
  var sel = mapSel(sectionId);
  var visible = this.isVisible(sel);
  assert.strictEqual(visible, false, 'Expected ' + sectionId + ' hidden');
});

Then('the {string} section is visible', function (sectionId) {
  var sel = mapSel(sectionId);
  var visible = this.isVisible(sel);
  assert.strictEqual(visible, true, 'Expected ' + sectionId + ' visible');
});

Then('a new todo item with title {string} appears in the list', function (title) {
  var exists = this.evaluate(liExists(title));
  assert.strictEqual(exists, true, 'Expected todo "' + title + '" to appear');
});

Then('the new-todo input is cleared', function () {
  var val = this.page.evaluate('document.querySelector(".new-todo").value');
  assert.strictEqual(val, '', 'Expected new-todo cleared');
});

Then('no new todo item is created', function () {
  var count = this.querySelectorAllCount('.todo-list li');
  assert.strictEqual(count, 0, 'Expected no todos created');
});

Then('the {string} item has the {string} class', function (title, cls) {
  var hasIt = this.evaluate(liClass(title, cls));
  assert.strictEqual(hasIt, true, 'Expected "' + title + '" has class "' + cls + '"');
});

Then('the {string} item does not have the {string} class', function (title, cls) {
  var hasIt = this.evaluate(liClass(title, cls));
  assert.strictEqual(hasIt, false, 'Expected "' + title + '" NOT class "' + cls + '"');
});

Then('the toggle checkbox on {string} is checked', function (title) {
  var checked = this.evaluate(toggleChecked(title));
  assert.strictEqual(checked, true, 'Expected toggle on "' + title + '" checked');
});

Then('the toggle checkbox on {string} is not checked', function (title) {
  var checked = this.evaluate(toggleChecked(title));
  assert.strictEqual(checked, false, 'Expected toggle on "' + title + '" not checked');
});

Then('the {string} checkbox is checked', function (id) {
  var checked = this.page.evaluate("document.querySelector('#" + esc(id) + "')?document.querySelector('#" + esc(id) + "').checked:false");
  assert.strictEqual(checked, true, 'Expected checkbox "' + id + '" checked');
});

Then('the {string} checkbox is not checked', function (id) {
  var checked = this.page.evaluate("document.querySelector('#" + esc(id) + "')?document.querySelector('#" + esc(id) + "').checked:false");
  assert.strictEqual(checked, false, 'Expected checkbox "' + id + '" not checked');
});

