});

Then('the todo label shows {string}', function (title) {
  var text = this.evaluate("(function(){var lb=" + findLabel(title) + ";return lb?lb.textContent:null;})()");
  assert.strictEqual(text, title, 'Expected label shows "' + title + '"');
});

Then('the todo label still shows {string}', function (title) {
